// Lo que el coordinador tiene que saber de kywai para reaccionar bien a cada petición: dónde trabaja el
// equipo, qué no puede hacer nadie, cuándo hace falta instalar algo, cuándo preguntar antes de lanzar trabajo y
// qué funciones tiene la app (para responder dudas sin crear tareas). Se añade a cada planificación; lo que
// cambia (permisos, carpeta, acceso web) se rellena en el momento.
import { relative, resolve, isAbsolute } from 'node:path'

export interface GuideEnv {
  /** Carpeta del código de kywai en este equipo (el clon de git que se actualiza), si se conoce. */
  codeDir: string | null
  /** Direcciones del acceso web para otros dispositivos (sin el código de acceso); vacío si está apagado. */
  webUrls: () => string[]
}

let env: GuideEnv = { codeDir: null, webUrls: () => [] }

export function setGuideEnv(e: Partial<GuideEnv>): void {
  env = { ...env, ...e }
}

export function guideEnv(): GuideEnv {
  return env
}

/** La carpeta es (o está dentro de) el código de kywai. */
export function isInside(dir: string | null | undefined, codeDir: string | null | undefined): boolean {
  if (!dir || !codeDir) return false
  const rel = relative(resolve(codeDir), resolve(dir))
  return rel === '' || (!rel.startsWith('..') && !isAbsolute(rel))
}

export interface GuideOptions {
  /** Carpeta donde trabaja el equipo en este proyecto. */
  projectDir: string
  /** Los agentes pueden instalar y usar internet (⚙ → Ajustes → «Permisos de los agentes»: Acceso completo). */
  fullAccess: boolean
  /** «Preguntarme antes»: lo que los agentes no tienen permitido se lo piden al usuario (y esperan su respuesta). */
  askAccess?: boolean
  /** El usuario revisa y aprueba cada plan antes de que empiece (⚙ → Ajustes → «Pedir mi visto bueno a cada plan»). */
  planApproval?: boolean
  /**
   * La petición (o la conversación reciente) habla de kywai en sí: entonces va la lista de funciones de la app
   * para responder dudas. Si no, se omite (son unos 5 000 caracteres que diluyen la atención en lo que se pide).
   */
  aboutApp?: boolean
  /** La petición la lanzó sola una rutina (su nombre): el usuario no está delante para contestar preguntas. */
  routine?: string
  /** Herramientas extra de cada agente (servidores MCP de Ajustes › Extensiones), ya en líneas para la guía. */
  extraTools?: string[]
  /**
   * Quien planifica puede leer los archivos del proyecto (Claude, Codex o Gemini de respaldo; Hermes no): entonces
   * las consultas del proyecto las mira y las responde él, en vez de encargarlas.
   */
  plannerReads?: boolean
}

/** Palabras con las que el usuario suele referirse a kywai y a sus funciones (sin tildes, en minúsculas). */
const APP_WORDS =
  /\b(ai ?cowork|cowork|hermes|coordinador|agentes?|robots?|orbita|movil|celular|telefono|apk|android|tailscale|acceso (web|remoto|desde)|navegador|cliente de escritorio|servidor|sincroniz\w*|actualiza\w*|cuotas?|consumo|tokens?|memoria|instrucciones del proyecto|\/model|modelo de hermes|voz|voces|microfono|dictado|musica|tema|temas|idiomas?|ingl[eé]s|english|language|modo demo|visto bueno|planes?|reiniciar|detener|reanudar|entregables?|espacio 3d|estacion|becarios?|rutinas?|webhooks?|programad[ao]s?|cron|plantillas?)\b/

/** ¿Habla de kywai (la app, el equipo, el móvil, las cuotas…)? Decide si el coordinador recibe la lista de funciones. */
export function mentionsApp(text: string): boolean {
  const t = text
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
  return APP_WORDS.test(t)
}

/**
 * Cómo se escribe lo que sale en el chat. El chat lo pinta como ChatGPT o Claude (párrafos con aire, listas
 * marcadas), pero solo se lee bien si el texto viene breve y ordenado: un muro de texto sigue siendo un muro.
 */
export const CHAT_STYLE =
  'empieza por el resultado o la respuesta en una o dos frases; después, párrafos cortos (2 o 3 frases) separados por una línea en blanco; los pasos, opciones o hallazgos en lista (numerada si hay orden), un punto por idea; **negrita** solo para lo que no se puede pasar por alto; títulos (##) solo si la respuesta es larga; para citar una parte de un documento, nómbrala con palabras («apartado 3.1» o su título), nunca con «§» ni otros símbolos o abreviaturas que el usuario tenga que adivinar. Todo lo que el usuario tenga que copiar y pegar (código, órdenes de terminal, JSON, una política, configuración, un .env…) va SIEMPRE en su propio bloque ``` con su lenguaje (```json, ```bash…), aunque sea una línea, para que salga en una tarjeta con botón de copiar; nunca suelto dentro de una frase ni de un punto de la lista (el chat se comería sus * y _ como cursiva y se copiaría roto): termina la frase en «:» y pon el bloque debajo. Entre `comillas` dentro de una frase, solo nombres cortos (un archivo, un botón, un comando de una palabra). Nada de muros de texto, de relleno ni de repetir lo que el usuario ya ve.'

